import java.util.Iterator;
import java.util.List;
import java.util.Random;

/**
 * A class representing shared characteristics of animals.
 *
 * @version 2022.03.01
 */
public abstract class Animal extends Organism
{
    // The level of food an animal has consumed, increases when it eats
    private int foodLevel;
    // Indicates whether an animal can give birth or not
    private boolean female;
    // Indicates whether the animal is nocturnal or not
    private boolean nocturnal;
    // The animal's age
    private double age;
    // Indicates whether the animal is sleeping or not
    private boolean sleeping;

    /**
     * Create a new animal at location in field.
     * 
     * @param randomAge If true, the animal will have a random age
     * @param field The field currently occupied.
     * @param location The location within the field.
     */
    public Animal(boolean randomAge, Field field, Location location)
    {
        super(randomAge, field, location);
        nocturnal = false;
        Random rand = Randomizer.getRandom();
        female = rand.nextBoolean();
        setWaterLevel(rand.nextInt(10) + 5);
        sleeping = false;
        if(!randomAge) {
            setAge(0);
            foodLevel = rand.nextInt(10) + 8;
        }
    }

    /**
     * Make this animal act - that is: make it do
     * whatever it wants/needs to do.
     * @param newAnimals A list to receive newly born animals.
     */
    public void act(List<Actor> newOrganisms) {
        // All animals eat; all organisms also increment age and water level
        super.act(newOrganisms);
        incrementHunger();
        if(isAlive() && !sleeping) {        
            // Move towards a source of food if found
            giveBirth(newOrganisms);  
            Location newLocation = null;
            if(getWaterLevel() < 3) {
                newLocation = findWater();
            }
            if (newLocation == null && getFoodLevel() < 8 && Randomizer.getRandom().nextDouble() <= getHuntProbability()) {
                newLocation = findFood(getPrey());
            }
            if (newLocation == null) {
                newLocation = findMate();
            }
            if(newLocation == null) { 
                // No food found - try to move to a free location.
                newLocation = getField().freeAdjacentLocation(getLocation());
            }

            // See if it was possible to move.
            if(newLocation != null) {
                setLocation(newLocation);
            }
            else {
                // Overcrowding.
                setDead();
            }
        }
        else if (sleeping) {
            // code for what to do when sleeping
            sleeping = false;
        }
    }

    /**
     * Move towards another animal of the same species to find a mate to breed with
     * 
     * @return The location of a potential mate if found, null if not
     */
    public Location findMate() 
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal != null && animal.getClass().equals(this.getClass())) {
                Animal mate = (Animal) animal;
                if (isFemale() != mate.isFemale()) {
                    Location freeLocation = field.freeAdjacentLocation(where);
                    if (freeLocation != null) {
                        return freeLocation;
                    }
                }
            }
        }
        return null;
    }

    /**
     * Look for prey adjacent to the current location.
     * Only the first live prey is eaten.
     * @return Where food was found, or null if it wasn't.
     */
    protected Location findFood(List<String> preyList)
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object food = field.getObjectAt(where);
            if(food!= null) {
                if(preyList.contains(food.getClass().getName())) {
                    Organism prey = (Organism) food;
                    if(prey.isAlive()) { 
                        prey.setDead();
                        int increment = prey.getFoodValue() + this.getFoodLevel();
                        this.setFoodLevel(increment);
                        int newWaterLevel = getWaterLevel() + 5;
                        this.setWaterLevel(newWaterLevel);
                        return where;  
                    }
                }
            }
        }
        return null;
    }

    /**
     * Make the animal more hungry. This could result in the animal's death.
     */
    public void incrementHunger()
    {
        foodLevel--;
        if(foodLevel <= 0) {
            setDead();
        }
    }

    /**
     * Check whether or not this animal is to give birth at this step.
     * New births will be made into free adjacent locations.
     * @param newAnimals A list to return newly born animals.
     * @return A list of the free adjacent locations for new young to be born into
     */
    protected List<Location> giveBirth(List<Actor> newAnimals)
    {
        // New animals are born into adjacent locations.
        // Get a list of adjacent free locations.
        Field field = getField();
        List<Location> free = field.getFreeAdjacentLocations(getLocation());
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            // can only breed if next to an animal of opposite sex
            if(animal != null && this.getClass().equals(animal.getClass())) {
                Animal mate = (Animal) animal;
                if (isFemale() != mate.isFemale()) {
                    return free;
                }
                else {
                    return null;
                }
            }
        }    
        return null;
    }

    /**
     * @param foodValue The level of food an animal has eaten
     */
    protected void setFoodLevel(int foodValue)
    {
        foodLevel = foodValue;
    }

    /** 
     * @return The level of food an animal has eaten
     */
    protected int getFoodLevel()
    {
        return foodLevel;
    }

    /** 
     * @return True if this animal is a female, capable of breeding
     */
    public boolean isFemale()
    {
        return female;
    }

    /** 
     * @return True if this animal is a female, capable of breeding
     */
    public void setNocturnal()
    {
        nocturnal = true;
    }

    /** 
     * @return True if this animal is nocturnal, false if not
     */
    public boolean isNocturnal()
    {
        return nocturnal;
    }

    /**
     * Sets the sleeping boolean variable to the opposite state it currently has.
     */
    public void setSleepStatus(){
        sleeping = ! sleeping;
    }

    /**
     * @return Returns list of prey for each animal
     */
    abstract public List<String> getPrey();

    /**
     * @return The probability that this animal successfully hunts when it is hungry.
     */
    protected double getHuntProbability()
    {
        return 1.0;
    }
}

import java.util.List;
import java.util.Random;

/**
 * Models behaviour of simple weather conditions in the simulation.
 * It can rain, be very hot or foggy, which in return affects how species behave.
 *
 * @version 2022.02.27
 */
public class Weather implements Actor
{
    // Probability of rain occurring
    private static final double RAIN_PROB = 0.12;
    // Probability of fog occurring
    private static final double FOG_PROB = 0.005;
    // Probability of a heatwave occurring 
    private static final double HEATWAVE_PROB = 0.0001;
    // Indicates whether new water sources need to be generated
    private boolean generateWater = false;

    /**
     * Constructor for objects of class Weather
     */
    public Weather() {}

    /**
     * Make the weather act - that is: make it do
     * whatever it wants/needs to do.
     * @param newActors A list to receive any species affected by the weather event
     */
    public void act(List<Actor> actorsList) {
        generateWater = false;
        // Generate one weather event per step using shared randomness.
        Random rand = Randomizer.getRandom();
        if (rand.nextDouble() <= RAIN_PROB) {
            makeRain(actorsList);
            generateWater = true;
        }
        else if (rand.nextDouble() <= FOG_PROB){
            makeFog(actorsList);
        }
        else if (rand.nextDouble() <= HEATWAVE_PROB) {
            makeHeatWave(actorsList);
        }
    }

    /**
     * What happens when rain occurs. 
     * Water value for all objects are increased by 5, which is the water value of rain.
     * This in turn affects each object's behaviour.
     * @param newActors A list to receive any species affected by the weather event
     */
    protected boolean makeRain(List<Actor> actorsList){
        adjustMoisture(actorsList, 5, 10);
        return true;
    }

    /**
     * What happens when fog occurs. 
     * Water value for some objects are increased by 2 
     * and causes animals to not be able to conduct normal behaviour when there is gof.
     * This in turn affects each object's behaviour.
     * @param newActors A list to receive any species affected by the weather event
     */
    protected void makeFog(List<Actor> actorsList) {
        for (Actor actor : actorsList) {
            if (actor instanceof Plant) {
                Plant plant = (Plant) actor;
                plant.setWaterLevel(plant.getWaterLevel() + 2);
            }
            else if (actor instanceof Animal) {
                Animal animal = (Animal) actor;
                animal.setSleepStatus();
            }
            else if (actor instanceof WaterSources){
                WaterSources source = (WaterSources) actor;
                source.setVolume(source.getVolume() + 2);
            }
        }
    }

    /**
     * What happens when a heatwave occurs. 
     * Water value for all objects is halved by 2 to show impact of extreme exposure to heat.
     * This in turn affects each object's behaviour.
     * @param newActors A list to receive any species affected by the weather event
     */
    protected void makeHeatWave(List<Actor> actorsList){
        for (Actor actor : actorsList) {
            if (actor instanceof Plant) {
                Plant plant = (Plant) actor;
                plant.setWaterLevel(plant.getWaterLevel() / 2);
            }
            else if (actor instanceof Animal) {
                Animal animal = (Animal) actor;
                animal.setWaterLevel(animal.getWaterLevel() / 2);
            }
            else if (actor instanceof WaterSources){
                WaterSources source = (WaterSources) actor;
                source.setVolume(source.getVolume() / 2);
            }
        }
    }

    /**
     * Increase hydration for living things and water volume for water sources.
     * @param actorsList The active actors.
     * @param organismDelta Water added to plants and animals.
     * @param waterDelta Water added to water sources.
     */
    private void adjustMoisture(List<Actor> actorsList, int organismDelta, int waterDelta)
    {
        for (Actor actor : actorsList) {
            if (actor instanceof Plant) {
                Plant plant = (Plant) actor;
                plant.setWaterLevel(plant.getWaterLevel() + organismDelta);
            }
            else if (actor instanceof Animal) {
                Animal animal = (Animal) actor;
                animal.setWaterLevel(animal.getWaterLevel() + organismDelta);
            }
            else if (actor instanceof WaterSources) {
                WaterSources source = (WaterSources) actor;
                source.setVolume(source.getVolume() + waterDelta);
            }
        }
    }

    /**
     * @return Whether or not the simulator should generate new water space
     * (if it has just rained)
     */
    public boolean generateNewWater() {
        return generateWater;
    }
}

import java.util.HashMap;

/**
 * This class collects and provides some statistical data on the state 
 * of a field. It is flexible: it will create and maintain a counter 
 * for any class of object that is found within the field.
 *
 * @version 2022.02.28
 */
public class FieldStats
{
    // Counters for each type of entity in the simulation.
    private HashMap<Class<?>, Counter> counters;
    // Whether the counters are currently up to date.
    private boolean countsValid;

    /**
     * Construct a FieldStats object.
     */
    public FieldStats()
    {
        counters = new HashMap<>();
        countsValid = true;
    }

    /**
     * Get details of what is in the field.
     * @param field The field to get details for.
     * @return A string describing what is in the field.
     */
    public String getPopulationDetails(Field field)
    {
        StringBuilder buffer = new StringBuilder();
        if(!countsValid) {
            generateCounts(field);
        }
        int totalCount = 0;
        for(Class<?> key : counters.keySet()) {
            Counter info = counters.get(key);
            totalCount += info.getCount();
            buffer.append(info.getName());
            buffer.append(": ");
            buffer.append(info.getCount());
            buffer.append(' ');
        }
        buffer.append(" Total: " + totalCount);
        return buffer.toString();
    }

    /**
     * Invalidate the current set of statistics; reset all 
     * counts to zero.
     */
    public void reset()
    {
        countsValid = false;
        for(Class<?> key : counters.keySet()) {
            Counter count = counters.get(key);
            count.reset();
        }
    }

    /**
     * Increment the count for one class of each object(animal, 
     * water sources, plants).
     * @param objectClass The class of object to increment.
     */
    public void incrementCount(Class<?> objectClass)
    {
        Counter count = counters.get(objectClass);
        if(count == null) {
            count = new Counter(objectClass.getName());
            counters.put(objectClass, count);
        }
        count.increment();
    }

    /**
     * Indicate that an object count has been completed.
     */
    public void countFinished()
    {
        countsValid = true;
    }

    /**
     * Determine whether the simulation is still viable.
     * I.e., should it continue to run.
     * @field The field to generate the stats for.
     * @return true If there is more than one species alive.
     */
    public boolean isViable(Field field)
    {
        // How many counts are non-zero.
        int nonZero = 0;
        if(!countsValid) {
            generateCounts(field);
        }
        for(Class<?> key : counters.keySet()) {
            Counter info = counters.get(key);
            if(info.getCount() > 0) {
                nonZero++;
            }
        }
        return nonZero > 1;
    }

    /**
     * Generate counts of the number of organisms and water sources there are.
     * These are not kept up to date as objects
     * are placed in the field, but only when a request
     * is made for the information.
     * @param field The field to generate the stats for.
     */
    private void generateCounts(Field field)
    {
        reset();
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Object occupant = field.getObjectAt(row, col);
                if(occupant != null) {
                    incrementCount(occupant.getClass());
                }
            }
        }
        countsValid = true;
    }
}

