  4	/**
  5	 * Models behaviour of simple weather conditions in the simulation.
  6	 * It can rain, be very hot or foggy, which in return affects how species behave.
  7	 *
  8	 * @version 2022.02.27
  9	 */
 10	public class Weather implements Actor
 11	{
 12	    // Probability of rain occurring
 13	    private static final double RAIN_PROB = 0.12;
 14	    // Probability of fog occurring
 15	    private static final double FOG_PROB = 0.005;
 16	    // Probability of a heatwave occurring 
 17	    private static final double HEATWAVE_PROB = 0.0001;
 18	    // Indicates whether new water sources need to be generated
 19	    private boolean generateWater = false;
 20	
 21	    /**
 22	     * Constructor for objects of class Weather
 23	     */
 24	    public Weather() {}
 25	
 26	    /**
 27	     * Make the weather act - that is: make it do
 28	     * whatever it wants/needs to do.
 29	     * @param newActors A list to receive any species affected by the weather event
 30	     */
 31	    public void act(List<Actor> actorsList) {
 32	        generateWater = false;
 33	        // Generate one weather event per step using shared randomness.
 34	        Random rand = Randomizer.getRandom();
 35	        if (rand.nextDouble() <= RAIN_PROB) {
 36	            makeRain(actorsList);
 37	            generateWater = true;
 38	        }
 39	        else if (rand.nextDouble() <= FOG_PROB){
 40	            makeFog(actorsList);
 41	        }
 42	        else if (rand.nextDouble() <= HEATWAVE_PROB) {
 43	            makeHeatWave(actorsList);
 44	        }
 45	    }
 46	
 47	    /**
 48	     * What happens when rain occurs. 
 49	     * Water value for all objects are increased by 5, which is the water value of rain.
 50	     * This in turn affects each object's behaviour.
 51	     * @param newActors A list to receive any species affected by the weather event
 52	     */
 53	    protected boolean makeRain(List<Actor> actorsList){
 54	        adjustMoisture(actorsList, 5, 10);
 55	        return true;
 56	    }
 57	
 58	    /**
 59	     * What happens when fog occurs. 
 60	     * Water value for some objects are increased by 2 
 61	     * and causes animals to not be able to conduct normal behaviour when there is gof.
 62	     * This in turn affects each object's behaviour.
 63	     * @param newActors A list to receive any species affected by the weather event
 64	     */
 65	    protected void makeFog(List<Actor> actorsList) {
 66	        for (Actor actor : actorsList) {
 67	            if (actor instanceof Plant) {
 68	                Plant plant = (Plant) actor;
 69	                plant.setWaterLevel(plant.getWaterLevel() + 2);
 70	            }
 71	            else if (actor instanceof Animal) {
 72	                Animal animal = (Animal) actor;
 73	                animal.setSleepStatus();
 74	            }
 75	            else if (actor instanceof WaterSources){
 76	                WaterSources source = (WaterSources) actor;
 77	                source.setVolume(source.getVolume() + 2);
 78	            }
 79	        }
 80	    }
 81	
 82	    /**
 83	     * What happens when a heatwave occurs. 
 84	     * Water value for all objects is halved by 2 to show impact of extreme exposure to heat.
 85	     * This in turn affects each object's behaviour.
 86	     * @param newActors A list to receive any species affected by the weather event
 87	     */
 88	    protected void makeHeatWave(List<Actor> actorsList){
 89	        for (Actor actor : actorsList) {
 90	            if (actor instanceof Plant) {
 91	                Plant plant = (Plant) actor;
 92	                plant.setWaterLevel(plant.getWaterLevel() / 2);
 93	            }
 94	            else if (actor instanceof Animal) {
 95	                Animal animal = (Animal) actor;
 96	                animal.setWaterLevel(animal.getWaterLevel() / 2);
 97	            }
 98	            else if (actor instanceof WaterSources){
 99	                WaterSources source = (WaterSources) actor;
100	                source.setVolume(source.getVolume() / 2);
101	            }
102	        }
103	    }
104	
105	    /**
106	     * Increase hydration for living things and water volume for water sources.
107	     * @param actorsList The active actors.
108	     * @param organismDelta Water added to plants and animals.
109	     * @param waterDelta Water added to water sources.
110	     */
111	    private void adjustMoisture(List<Actor> actorsList, int organismDelta, int waterDelta)
112	    {
113	        for (Actor actor : actorsList) {
114	            if (actor instanceof Plant) {
115	                Plant plant = (Plant) actor;
116	                plant.setWaterLevel(plant.getWaterLevel() + organismDelta);
117	            }
118	            else if (actor instanceof Animal) {
119	                Animal animal = (Animal) actor;
120	                animal.setWaterLevel(animal.getWaterLevel() + organismDelta);
121	            }
122	            else if (actor instanceof WaterSources) {
123	                WaterSources source = (WaterSources) actor;
124	                source.setVolume(source.getVolume() + waterDelta);
125	            }
126	        }
127	    }
128	
129	    /**
130	     * @return Whether or not the simulator should generate new water space
131	     * (if it has just rained)
132	     */
133	    public boolean generateNewWater() {
134	        return generateWater;
135	    }
136	}

