  5	/**
  6	 * A class representing shared characteristics of animals.
  7	 *
  8	 * @version 2022.03.01
  9	 */
 10	public abstract class Animal extends Organism
 11	{
 12	    // The level of food an animal has consumed, increases when it eats
 13	    private int foodLevel;
 14	    // Indicates whether an animal can give birth or not
 15	    private boolean female;
 16	    // Indicates whether the animal is nocturnal or not
 17	    private boolean nocturnal;
 18	    // The animal's age
 19	    private double age;
 20	    // Indicates whether the animal is sleeping or not
 21	    private boolean sleeping;
 22	    
 23	    /**
 24	     * Create a new animal at location in field.
 25	     * 
 26	     * @param randomAge If true, the animal will have a random age
 27	     * @param field The field currently occupied.
 28	     * @param location The location within the field.
 29	     */
 30	    public Animal(boolean randomAge, Field field, Location location)
 31	    {
 32	        super(randomAge, field, location);
 33	        nocturnal = false;
 34	        Random rand = Randomizer.getRandom();
 35	        female = rand.nextBoolean();
 36	        setWaterLevel(rand.nextInt(10) + 5);
 37	        sleeping = false;
 38	        if(!randomAge) {
 39	            setAge(0);
 40	            foodLevel = rand.nextInt(10) + 8;
 41	        }
 42	    }
 43	    
 44	    /**
 45	     * Make this animal act - that is: make it do
 46	     * whatever it wants/needs to do.
 47	     * @param newAnimals A list to receive newly born animals.
 48	     */
 49	    public void act(List<Actor> newOrganisms) {
 50	        // All animals eat; all organisms also increment age and water level
 51	        super.act(newOrganisms);
 52	        incrementHunger();
 53	        if(isAlive() && !sleeping) {        
 54	            // Move towards a source of food if found
 55	            giveBirth(newOrganisms);  
 56	            Location newLocation = null;
 57	            if(getWaterLevel() < 3) {
 58	                newLocation = findWater();
 59	            }
 60	            if (newLocation == null && getFoodLevel() < 8 && Randomizer.getRandom().nextDouble() <= getHuntProbability()) {
 61	                newLocation = findFood(getPrey());
 62	            }
 63	            if (newLocation == null) {
 64	                newLocation = findMate();
 65	            }
 66	            if(newLocation == null) { 
 67	                // No food found - try to move to a free location.
 68	                newLocation = getField().freeAdjacentLocation(getLocation());
 69	            }
 70	            
 71	            // See if it was possible to move.
 72	            if(newLocation != null) {
 73	                setLocation(newLocation);
 74	            }
 75	            else {
 76	                // Overcrowding.
 77	                setDead();
 78	            }
 79	        }
 80	        else if (sleeping) {
 81	            // code for what to do when sleeping
 82	            sleeping = false;
 83	        }
 84	    }
 85	    
 86	    /**
 87	     * Move towards another animal of the same species to find a mate to breed with
 88	     * 
 89	     * @return The location of a potential mate if found, null if not
 90	     */
 91	    public Location findMate() 
 92	    {
 93	        Field field = getField();
 94	        List<Location> adjacent = field.adjacentLocations(getLocation());
 95	        Iterator<Location> it = adjacent.iterator();
 96	        while(it.hasNext()) {
 97	            Location where = it.next();
 98	            Object animal = field.getObjectAt(where);
 99	            if(animal != null && animal.getClass().equals(this.getClass())) {
100	                Animal mate = (Animal) animal;
101	                if (isFemale() != mate.isFemale()) {
102	                    Location freeLocation = field.freeAdjacentLocation(where);
103	                    if (freeLocation != null) {
104	                        return freeLocation;
105	                    }
106	                }
107	            }
108	        }
109	        return null;
110	    }
111	    
112	    /**
113	     * Look for prey adjacent to the current location.
114	     * Only the first live prey is eaten.
115	     * @return Where food was found, or null if it wasn't.
116	     */
117	    protected Location findFood(List<String> preyList)
118	    {
119	        Field field = getField();
120	        List<Location> adjacent = field.adjacentLocations(getLocation());
121	        Iterator<Location> it = adjacent.iterator();
122	        while(it.hasNext()) {
123	            Location where = it.next();
124	            Object food = field.getObjectAt(where);
125	            if(food!= null) {
126	                if(preyList.contains(food.getClass().getName())) {
127	                    Organism prey = (Organism) food;
128	                    if(prey.isAlive()) { 
129	                        prey.setDead();
130	                        int increment = prey.getFoodValue() + this.getFoodLevel();
131	                        this.setFoodLevel(increment);
132	                        int newWaterLevel = getWaterLevel() + 5;
133	                        this.setWaterLevel(newWaterLevel);
134	                        return where;  
135	                    }
136	                }
137	            }
138	        }
139	        return null;
140	    }
141	    
142	    /**
143	     * Make the animal more hungry. This could result in the animal's death.
144	     */
145	    public void incrementHunger()
146	    {
147	        foodLevel--;
148	        if(foodLevel <= 0) {
149	            setDead();
150	        }
151	    }
152	    
153	    /**
154	     * Check whether or not this animal is to give birth at this step.
155	     * New births will be made into free adjacent locations.
156	     * @param newAnimals A list to return newly born animals.
157	     * @return A list of the free adjacent locations for new young to be born into
158	     */
159	    protected List<Location> giveBirth(List<Actor> newAnimals)
160	    {
161	        // New animals are born into adjacent locations.
162	        // Get a list of adjacent free locations.
163	        Field field = getField();
164	        List<Location> free = field.getFreeAdjacentLocations(getLocation());
165	        List<Location> adjacent = field.adjacentLocations(getLocation());
166	        Iterator<Location> it = adjacent.iterator();
167	        while(it.hasNext()) {
168	            Location where = it.next();
169	            Object animal = field.getObjectAt(where);
170	            // can only breed if next to an animal of opposite sex
171	            if(animal != null && this.getClass().equals(animal.getClass())) {
172	                Animal mate = (Animal) animal;
173	                if (isFemale() != mate.isFemale()) {
174	                    return free;
175	                }
176	            }
177	        }    
178	        return null;
179	    }
180	    
181	    /**
182	     * @param foodValue The level of food an animal has eaten
183	     */
184	    protected void setFoodLevel(int foodValue)
185	    {
186	        foodLevel = foodValue;
187	    }
188	    
189	    /** 
190	     * @return The level of food an animal has eaten
191	     */
192	    protected int getFoodLevel()
193	    {
194	        return foodLevel;
195	    }
196	    
197	    /** 
198	     * @return True if this animal is a female, capable of breeding
199	     */
200	    public boolean isFemale()
201	    {
202	        return female;
203	    }
204	    
205	    /** 
206	     * @return True if this animal is a female, capable of breeding
207	     */
208	    public void setNocturnal()
209	    {
210	        nocturnal = true;
211	    }
212	    
213	    /** 
214	     * @return True if this animal is nocturnal, false if not
215	     */
216	    public boolean isNocturnal()
217	    {
218	        return nocturnal;
219	    }
220	    
221	    /**
222	     * Sets the sleeping boolean variable to the opposite state it currently has.
223	     */
224	    public void setSleepStatus(){
225	        sleeping = ! sleeping;
226	    }
227	    
228	    /**
229	     * @return Returns list of prey for each animal
230	     */
231	    abstract public List<String> getPrey();
232	
233	    /**
234	     * @return The probability that this animal successfully hunts when it is hungry.
235	     */
236	    protected double getHuntProbability()
237	    {
238	        return 1.0;
239	    }
240	}

