123	    /**
124	     * Look for water adjacent to the organism's current location
125	     * @return Where water was found, or null if it wasn't 
126	     */
127	    protected Location findWater() {
128	        Field field = getField();
129	        List<Location> adjacent = field.adjacentLocations(getLocation());
130	        Iterator<Location> it = adjacent.iterator();
131	        while(it.hasNext()){
132	            Location where = it.next();
133	            Object waterSource = field.getObjectAt(where);
134	            if(waterSource instanceof Lake) {
135	                Lake lake = (Lake) waterSource;
136	                if(lake.getVolume() <= 0){
137	                    lake.setDead();
138	                    return null;
139	                }
140	                int waterDrawn = Math.min(lake.getWaterValue(), lake.getVolume());
141	                setWaterLevel(getWaterLevel() + waterDrawn);
142	                lake.reduceVolume(waterDrawn);
143	                if (lake.getVolume() <= 0) {
144	                    lake.setDead();
145	                }
146	                return where;
147	            }
148	        }
149	        return null;
150	    }
151	    
