153	     * Lower's the organism's water level - may result in its death
154	     */
155	    public void decreaseWaterLevel(){
156	        int newWaterLevel = getWaterLevel() - 1;
157	        setWaterLevel(newWaterLevel);
158	        if(getWaterLevel() <=0) {
159	            setDead();
160	        }
161	    }
