142	     * in the parameter. 
143	     * @param waterValue The value you want to deduct from the volume of 
144	     *                   the water source.
145	     */
146	    public void reduceVolume(int waterValue) {
147	        //Used when water is drunk by an animal or accessed by a plant. 
148	        //waterValue would be the water value of the water source.
149	        volumeLevel = volumeLevel - waterValue;
150	        if (volumeLevel <= 0) {
151	            volumeLevel = 0;
152	            setDead();
153	        }
154	    }
