  8	/**
  9	 * A simple predator-prey simulator, based on a rectangular field
 10	 * containing rabbits and foxes.
 11	 *
 12	 * @version 2022.03.01
 13	 */
 14	public class Simulator
 15	{
 16	     // Constants representing configuration information for the simulation.
 17	    // The default width for the grid.
 18	    private static final int DEFAULT_WIDTH = 150;
 19	    // The default depth of the grid.
 20	    private static final int DEFAULT_DEPTH = 120;
 21	    // The probability that a hyena will be created in any given grid position.
 22	    private static final double HYENA_CREATION_PROBABILITY = 0.02;
 23	    // The probability that a lion will be created in any given grid position.
 24	    private static final double LION_CREATION_PROBABILITY = 0.02;
 25	    // The probability that a gazelle will be created in any given grid position.
 26	    private static final double GAZELLE_CREATION_PROBABILITY = 0.02;    
 27	    // The probability that a mouse will be created in any given grid position.
 28	    private static final double MOUSE_CREATION_PROBABILITY = 0.02; 
 29	    // The probability that a fennec fox will be created in any given grid position.
 30	    private static final double FENNECFOX_CREATION_PROBABILITY = 0.02;  
 31	    // The probability that grass will be created in any given grid position.
 32	    private static final double GRASS_CREATION_PROBABILITY = 0.2;  
 33	    // The probability that a lake will be created in any given grid position.
 34	    private static final double LAKE_CREATION_PROBABILITY = 0.005;
 35	    // List of all actors in simulation
 36	    private List<Actor> actors;
 37	    // List of potential diseases that could occur in simulation
 38	    private List<Disease> diseases;
 39	    // The current state of the field.
 40	    private Field field;
 41	    // The current step of the simulation.
 42	    private int step;
 43	    // A graphical view of the simulation.
 44	    private SimulatorView view;
 45	    // Whether it is currently day or night - determines each animal's behaviour
 46	    private boolean nightTime;
 47	    
 48	    /**
 49	     * Construct a simulation field with default size.
 50	     */
 51	    public Simulator()
 52	    {
 53	        this(DEFAULT_DEPTH, DEFAULT_WIDTH);
 54	    }
 55	    
 56	    /**
 57	     * Create a simulation field with the given size.
 58	     * @param depth Depth of the field. Must be greater than zero.
 59	     * @param width Width of the field. Must be greater than zero.
 60	     */
 61	    public Simulator(int depth, int width)
 62	    {
 63	        if(width <= 0 || depth <= 0) {
 64	            System.out.println("The dimensions must be greater than zero.");
 65	            System.out.println("Using default values.");
 66	            depth = DEFAULT_DEPTH;
 67	            width = DEFAULT_WIDTH;
 68	        }
 69	        // Starts simulator during day time
 70	        nightTime = false;
 71	        
 72	        // Creates list to hold each actor
 73	        actors = new ArrayList<>();
 74	        field = new Field(depth, width);
 75	        
 76	        // Create a view of the state of each location in the field.
 77	        view = new SimulatorView(depth, width, this);
 78	        view.setColor(Gazelle.class, Color.ORANGE);
 79	        view.setColor(Lion.class, Color.YELLOW);
 80	        view.setColor(Hyena.class, Color.RED);
 81	        view.setColor(Mouse.class, Color.GRAY);
 82	        view.setColor(FennecFox.class, Color.MAGENTA);
 83	        view.setColor(Grass.class, Color.GREEN);
 84	        view.setColor(Lake.class, Color.BLUE);
 85	        
 86	        // Setup a valid starting point.
 87	        reset();
 88	    }
 89	    
 90	    /**
 91	     * Run the simulation from its current state for a reasonably long period,
 92	     * (500 steps).
 93	     */
 94	    public void runLongSimulation()
 95	    {
 96	        simulate(750);
 97	    }
 98	    
 99	    /**
100	     * Run the simulation from its current state for the given number of steps.
101	     * Stop before the given number of steps if it ceases to be viable.
102	     * @param numSteps The number of steps to run for.
103	     */
104	    public void simulate(int numSteps)
105	    {
106	        for(int step = 1; step <= numSteps && view.isViable(field); step++) {
107	            simulateOneStep();
108	            delay(60);   // uncomment this to run more slowly  
109	        }
110	    }
111	    
112	    /**
113	     * Run the simulation from its current state for a single step.
114	     * Iterate over the whole field updating the state of each animal.
115	     */
116	    public void simulateOneStep()
117	    {
118	        step++;
119	        
120	        // Alternates between day and night time every 2 steps
121	        if (step > 2 && step % 2 == 1) {
122	            nightTime = !nightTime;
123	        }
124	        
125	        // Provide space for newborn organisms
126	        List<Actor> newOrganisms = new ArrayList<>();   
127	
128	        Weather weather = null;
129	        
130	        // Let all actors act
131	        Iterator<Actor> it = actors.iterator();
132	        while(it.hasNext()) {
133	            boolean canAct = true;
134	            Actor actor = it.next();
135	            if (actor instanceof Weather) {
136	                weather = (Weather) actor;
137	            }
138	            if (actor instanceof Organism) {
139	                // low chance of each animal being infected wiht a disease
140	                generateDisease(actor);
141	                Organism organism = (Organism) actor;
142	                if (organism instanceof Animal) {
143	                    Animal animal = (Animal) organism;   
144	                    // animals only act during certain times of day (i.e. if day but nocturnal, won't act)
145	                    if (nightTime != animal.isNocturnal()) {
146	                        canAct = false;
147	                    }
148	                }
149	                if (canAct) {
150	                    actor.act(newOrganisms);
151	                }
152	                if(!(organism.isAlive())) {
153	                    it.remove();
154	                }
155	            }
156	            else {
157	                actor.act(actors);  
158	            }
159	            
160	            // Removes any empty water sources from the field
161	            if (actor instanceof WaterSources) {
162	                WaterSources water = (WaterSources) actor;
163	                // if a water source is empty, remove it from simulation
164	                if (water.isEmpty()) {
165	                    it.remove();
166	                }
167	            }
168	        }
169	        // Add the newly born animals to the main lists.
170	        actors.addAll(newOrganisms);      
171	        
172	        // If it has rained, create new water
173	        if (weather != null && weather.generateNewWater()) {
174	            generateWater();
175	        }
176	        
177	        view.showStatus(step, field);
178	    }
179	        
180	    /**
181	     * Reset the simulation to a starting position.
182	     */
183	    public void reset()
184	    {
185	        step = 0;
186	        actors.clear();
187	
188	        populate();
189	        nightTime = false;
190	        
191	        // Show the starting state in the view.
192	        view.showStatus(step, field);
193	    }
194	    
195	    /**
196	     * Randomly populate the field with animals.
197	     */
198	    private void populate()
199	    {
200	        Random rand = Randomizer.getRandom();
201	        field.clear();
202	        
203	        // Creates default actors (diseases and weather)
204	        diseases = new ArrayList<>();
205	        Disease covid = new Covid(field);
206	        Disease leptospirosis = new Leptospirosis(field);
207	        diseases.addAll(Arrays.asList(covid, leptospirosis));
208	        
209	        Weather weather = new Weather();
210	        
211	        actors.addAll(diseases);
212	        actors.add(weather);
213	        for(int row = 0; row < field.getDepth(); row++) {
214	            for(int col = 0; col < field.getWidth(); col++) {
215	                if(rand.nextDouble() <= LAKE_CREATION_PROBABILITY) {
216	                    Location location = new Location(row, col);
217	                    Lake lake = new Lake(true, field, location);
218	                    actors.add(lake);
219	                    // creates lakes over an area of 9 grid spaces
220	                    List<Location> adjacent = field.adjacentLocations(location);
221	                    for (int i = 0; i<adjacent.size(); i++) {
222	                        Lake lake2 = new Lake(true, field, adjacent.get(i));
223	                        actors.add(lake2);
224	                    }
225	                }
226	                else if(rand.nextDouble() <= HYENA_CREATION_PROBABILITY) {
227	                    Location location = new Location(row, col);
228	                    Hyena hyena = new Hyena(true, field, location);
229	                    actors.add(hyena);
230	                }
231	                else if(rand.nextDouble() <= LION_CREATION_PROBABILITY) {
232	                    Location location = new Location(row, col);
233	                    Lion lion = new Lion(true, field, location);
234	                    actors.add(lion);
235	                }
236	                else if(rand.nextDouble() <= GAZELLE_CREATION_PROBABILITY) {
237	                    Location location = new Location(row, col);
238	                    Gazelle gazelle= new Gazelle(true, field, location);
239	                    actors.add(gazelle);
240	                }
241	                else if(rand.nextDouble() <= MOUSE_CREATION_PROBABILITY) {
242	                    Location location = new Location(row, col);
243	                    Mouse mouse= new Mouse(true, field, location);
244	                    actors.add(mouse);
245	                }
246	                else if(rand.nextDouble() <= FENNECFOX_CREATION_PROBABILITY) {
247	                    Location location = new Location(row, col);
248	                    FennecFox fennecFox= new FennecFox(true, field, location);
249	                    actors.add(fennecFox);
250	                }
251	                else if(rand.nextDouble() <= GRASS_CREATION_PROBABILITY) {
252	                    Location location = new Location(row, col);
253	                    Grass grass = new Grass(true, field, location);
254	                    actors.add(grass);
255	                }
256	                // else leave the location empty.
257	            }
258	        }
259	    }
260

260	    
261	    /**
262	     * Random chance of a disease being generated in the population
263	     * @param actor An individual which could be infected
264	     */
265	    private void generateDisease(Actor actor) 
266	    {
267	        Random rand = Randomizer.getRandom();
268	        for (Disease disease: diseases) {
269	            // random low chance of an individual developing a disease
270	            if(rand.nextDouble() <= disease.getProbability()) {
271	                // only infects certain species (must be organisms)
272	                if (disease.getSpecies().contains(actor.getClass().getName())) {
273	                    // adds infected individual to diseased list and sets infected to true
274	                    disease.addIndividual(actor);
275	                    Organism organism = (Organism) actor;
276	                    organism.setInfected();
277	                }
278	            }
279	        }
280	    }
281	    
282	    /** 
283	     * Creates random water spaces in free locations in field
284	     * Used when it rains to create new water sources
285	     */
286	    public void generateWater()
287	    {
288	        Random rand = Randomizer.getRandom();
289	        for(int row = 0; row < field.getDepth(); row++) {
290	            for(int col = 0; col < field.getWidth(); col++) {
291	                // if there is an empty space, chance of creating a new water source
292	                if (rand.nextDouble() < LAKE_CREATION_PROBABILITY/120) {
293	                    Location location = new Location(row, col);
294	                    Lake lake = new Lake(true, field, location);
295	                    actors.add(lake);
296	                    List<Location> adjacent = field.adjacentLocations(location);
297	                    for (int i = 0; i<adjacent.size(); i++) {
298	                        if (rand.nextBoolean()) {
299	                            Lake lake2 = new Lake(true, field, adjacent.get(i));
300	                            actors.add(lake2);
301	                        }
302	                    }
303	                }
304	            }
305	        }
306	    }
